        if (tag === 'path') p.addPath(new Path2D(el.getAttribute('d') || ''));
        else if (tag === 'ellipse') p.ellipse(num(el, 'cx'), num(el, 'cy'), num(el, 'rx'), num(el, 'ry'), 0, 0, TAU);
