  // the picture `key` into the square (x, y, size) of ctx; `side`: the colour of its id="side" shape
  function paint(ctx, key, x, y, size, side = null) {
    const root = tree(key); const [, , vw, vh] = (root.getAttribute('viewBox') || '0 0 128 128').split(/\s+/).map(Number);
    ctx.save(); ctx.translate(x, y); ctx.scale(size / vw, size / vh); walk(ctx, root, side); ctx.restore();
  }
  // each game's sides: the colour the side shape takes (오목·오델로 흑/백, 사목 빨강/노랑, 윷놀이 파랑/빨강 + its number)
  const SIDES = { omok: { black: '#26282e', white: '#f4f1ea' }, othello: { black: '#26282e', white: '#f4f1ea' }, connect4: { black: '#e11d48', white: '#facc15' }, yut: { black: '#2563eb', white: '#ef4444' } };
  const piece = (family, key) => ({
    stone: (ctx, r, color, label) => { paint(ctx, key, -r * 1.12, -r * 1.12, r * 2.24, SIDES[family][color === 'white' ? 'white' : 'black']); if (family === 'yut') badge(ctx, r, label); },
    preview: (ctx, w, h) => {
      ctx.fillStyle = '#e9e1cf'; ctx.fillRect(0, 0, w, h); const s = Math.min(w / 2, h) * 0.86;
      for (const [cx, color] of [[w * 0.27, 'black'], [w * 0.73, 'white']]) paint(ctx, key, cx - s / 2, (h - s) / 2, s, SIDES[family][color]);
    },
  });
  const theme = (key, board) => ({ board: { paint: (ctx, w, h) => paint(ctx, key, 0, 0, Math.max(w, h)), ...board }, preview: (ctx, w, h) => paint(ctx, key, (w - Math.max(w, h)) / 2, (h - Math.max(w, h)) / 2, Math.max(w, h)) });
